        for name in os.listdir(TICKETS_DIR):
            path = os.path.join(TICKETS_DIR, name)
            if os.path.isdir(path):
                stack.append((path, 1))
            elif os.path.isfile(path) and (name.startswith(".") or DUPLICATE_MARKER in name.lower()):
                texts.append(_read(path))
